def get_effective_css() -> str:
    """
    Returns bundled CSS from disk if available, otherwise returns embedded CSS.
    """
    script_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(os.path.dirname(script_dir), "antigravity-chat-rtl.css"),
        os.path.join(script_dir, "antigravity-chat-rtl.css"),
        "src/antigravity-chat-rtl.css",
        "antigravity-chat-rtl.css"
    ]
    for c in candidates:
        if os.path.isfile(c):
            try:
                with open(c, "r", encoding="utf-8") as f:
                    content = f.read().strip()
                    if content:
                        return content
            except Exception:
                pass
    return RTL_CSS
